p-valid-palindrome-ignoring-punctuation-.starter:
// Return true if s reads the same both ways, looking only at letters and digits and ignoring case.
function isPalindrome(s: string): boolean {
  throw new Error('Not implemented');
}

p-valid-palindrome-ignoring-punctuation-.solution:
const isAlnum = (ch: string) => /[a-z0-9]/i.test(ch);
function isPalindrome(s: string): boolean {
  let left = 0;
  let right = s.length - 1;
  while (left < right) {
    if (!isAlnum(s[left])) left++;
    else if (!isAlnum(s[right])) right--;
    else if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;
    else {
      left++;
      right--;
    }
  }
  return true;
}

