p-dedupe-records-by-key-keeping-the-firs.starter:
// Return the items, keeping only the first item for each key(item), in the original order.
function uniqueBy<T, K>(items: readonly T[], key: (item: T) => K): T[] {
  throw new Error('Not implemented');
}

p-dedupe-records-by-key-keeping-the-firs.solution:
function uniqueBy<T, K>(items: readonly T[], key: (item: T) => K): T[] {
  const seen = new Set<K>();
  const out: T[] = [];
  for (const item of items) {
    const k = key(item);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(item);
  }
  return out;
}

