p-flatten-a-nested-array-to-a-given-dept.starter:
type Nested<T> = T | Nested<T>[];

// Flatten nested arrays up to `depth` levels (all levels by default), without Array.prototype.flat.
function flatten<T>(items: readonly Nested<T>[], depth = Infinity): Nested<T>[] {
  throw new Error('Not implemented');
}

p-flatten-a-nested-array-to-a-given-dept.solution:
type Nested<T> = T | Nested<T>[];
function flatten<T>(items: readonly Nested<T>[], depth = Infinity): Nested<T>[] {
  const out: Nested<T>[] = [];
  for (const item of items) {
    if (Array.isArray(item) && depth > 0) out.push(...flatten(item, depth - 1));
    else out.push(item);
  }
  return out;
}

