p-second-largest-distinct-number.starter:
// Return the second largest distinct value, or null if there is none.
function secondLargest(nums: readonly number[]): number | null {
  throw new Error('Not implemented');
}

p-second-largest-distinct-number.solution:
function secondLargest(nums: readonly number[]): number | null {
  let first: number | null = null;
  let second: number | null = null;
  for (const n of nums) {
    if (first === null || n > first) {
      second = first;
      first = n;
    } else if (n < first && (second === null || n > second)) {
      second = n;
    }
  }
  return second;
}

