p-group-records-by-a-key.starter:
// Return the items grouped by keyFn(item), each group in input order, without using Object.groupBy.
// Follow-up: what goes wrong with a key of '__proto__', and how would you avoid it?
function groupBy<T>(items: readonly T[], keyFn: (item: T) => string): Record<string, T[]> {
  throw new Error('Not implemented');
}

p-group-records-by-a-key.solution:
function groupBy<T>(items: readonly T[], keyFn: (item: T) => string): Record<string, T[]> {
  const groups: Record<string, T[]> = {};
  for (const item of items) {
    const key = keyFn(item);
    (groups[key] ??= []).push(item);
  }
  return groups;
}

