  for (const item of items) {
    const key = keyFn(item);
    (groups[key] ??= []).push(item);
  }
  return groups;
}

const runs = [
  { id: 'r1', status: 'done' },
  { id: 'r2', status: 'failed' },
  { id: 'r3', status: 'done' },
];
assert.deepEqual(groupBy(runs, (r) => r.status), {
  done: [runs[0], runs[2]],
  failed: [runs[1]],
