p-rotate-an-array-by-k-steps.solution:
function reverse(a: number[], from: number, to: number): void {
  while (from < to) {
    [a[from], a[to]] = [a[to], a[from]];
    from++;
    to--;
  }
}
function rotate(nums: number[], k: number): void {
  const n = nums.length;
  if (n === 0) return;
  k %= n;
  reverse(nums, 0, n - 1);
  reverse(nums, 0, k - 1);
  reverse(nums, k, n - 1);
}

