p-top-k-most-frequent-words-with-tie-bre.starter:
// Return the k most frequent words, by count descending and then alphabetically; [] when k <= 0.
function topKWords(words: readonly string[], k: number): string[] {
  throw new Error('Not implemented');
}

p-top-k-most-frequent-words-with-tie-bre.solution:
function topKWords(words: readonly string[], k: number): string[] {
  const counts = new Map<string, number>();
  for (const w of words) counts.set(w, (counts.get(w) ?? 0) + 1);
  return [...counts]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .slice(0, Math.max(0, k)) // a negative k would make slice drop items from the end
    .map(([w]) => w);
}

